    Faq = @(
      @('Can one seed packet label template cover many varieties?', 'A common layout can help recognition, but each variety still needs its own approved name, artwork, information and quantity. Review all versions at final size.'),
      @('How small can seed packet text be?', 'There is no universal size to promise from a screen mockup. Print a final-size proof on the chosen material and check the important text under normal reading conditions.'),
      @('Who confirms germination or growing claims?', 'The responsible seller supplies and approves all variety, growing and market-specific statements. The printing review focuses on artwork reproduction and legibility, not independent validation of those claims.')
